2001	    for(w = 0, i = 0; w < HUFF_BC;) {
2002	        value = (p[i] & nibble_mask) >> nibble_shift;
2003	
2004	        if(nibble_mask == 0x0F)
2005	            ++i;
2006	
2007	        nibble_mask ^= 0xFF;
2008	        nibble_shift ^= 4;
